    referenceUrl: "https://aws.amazon.com/compliance/soc-faqs/",
    referenceLabel: "AWS SOC FAQs",
    consoleUrl: "https://console.aws.amazon.com/artifact/reports",
    consoleLabel: "AWS Artifact > Reports",
